UPDATE catalog SET data = '{"id":"gutenberg-100","title":"The Complete Works of William Shakespeare","author":"Shakespeare, William","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/6cfad8a2ef6209462f45bf6330b0f5b501fe8ca16f3e167bde97e4d573e717a3.jpg","categoryId":"fiction","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/72397ff2459a5948eda764bae9b036c0037ccbf3fd93c8aba610208815784e88.epub","fileSizeBytes":2880260,"contentVersion":1,"isFeatured":true,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"language":"en","source":"gutendex","sourceId":100,"sourceUrl":"https://www.gutenberg.org/ebooks/100","rights":"PUBLIC_DOMAIN_US","downloadCount":96639,"subjects":["English drama -- Early modern and Elizabethan, 1500-1600"],"description":"This collection gathers Shakespeare''s plays, poems and sonnets in one edition, from the histories and comedies to the great tragedies. It includes enduring characters such as Hamlet, Macbeth, Lear, Rosalind and Falstaff, and the sonnets'' meditations on love and time. Readers can follow the range of Shakespeare''s language, stagecraft and insight into power, jealousy and mercy.","contentHash":"72397ff2459a5948eda764bae9b036c0037ccbf3fd93c8aba610208815784e88","license":"Public domain (Project Gutenberg)"}' WHERE id = 'gutenberg-100';
UPDATE catalog SET data = '{"id":"gutenberg-11","title":"Alice''s Adventures in Wonderland","author":"Carroll, Lewis","language":"en","categoryId":"fiction","sourceUrl":"https://www.gutenberg.org/ebooks/11","source":"Project Gutenberg / Gutendex","description":"Alice follows a bored girl down a rabbit hole into a world where nothing behaves as it should. She meets the White Rabbit, the Cheshire Cat, the Mad Hatter and the Queen of Hearts, and grows and shrinks as she tries to make sense of the rules. The story blends nonsense, wordplay and satire into one of the most influential children''s books in English.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/5b60442ac47c9b95d6abda3ddf631e5b5c5bff5ea27f310294257713ef51ac35.jpg","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/12cbc3610260503383ad7ecf800beb0d885a6011e15900b2bf61cecfc571d6c8.epub","fileSizeBytes":188960,"contentHash":"12cbc3610260503383ad7ecf800beb0d885a6011e15900b2bf61cecfc571d6c8","contentVersion":1,"isFeatured":true,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"license":"Public domain (Project Gutenberg)"}' WHERE id = 'gutenberg-11';
