UPDATE catalog SET data = '{"id":"gutenberg-1260","title":"Jane Eyre: An Autobiography","author":"Brontë, Charlotte","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/7bdd676e8d4051a765ffad1f88223f3ae7fe4a8ce0458f30414a2f5a31951f93.jpg","categoryId":"romance","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/7dbcc5804e9875f4c15c4b54f14168a0d19ab5b155d42acbbfc3d309d889db0b.epub","fileSizeBytes":3095830,"contentVersion":1,"isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"language":"en","source":"gutendex","sourceId":1260,"sourceUrl":"https://www.gutenberg.org/ebooks/1260","rights":"PUBLIC_DOMAIN_US","downloadCount":95505,"subjects":["Bildungsromans","Charity-schools -- Fiction","Country homes -- Fiction","England -- Fiction","Fathers and daughters -- Fiction","Governesses -- Fiction","Love stories","Married people -- Fiction","Mentally ill women -- Fiction","Orphans -- Fiction","Young women -- Fiction"],"description":"Jane Eyre is an orphan raised by a cruel aunt and sent to the harsh Lowood school, where she learns endurance and independence. She becomes a governess at Thornfield Hall and falls in love with its brooding master, Edward Rochester. A secret in the house forces her to choose between passion, principle and her own self-respect.","contentHash":"7dbcc5804e9875f4c15c4b54f14168a0d19ab5b155d42acbbfc3d309d889db0b","license":"Public domain (Project Gutenberg)"}' WHERE id = 'gutenberg-1260';
UPDATE catalog SET data = '{"id":"gutenberg-1342","title":"Pride and Prejudice","author":"Austen, Jane","language":"en","categoryId":"romance","sourceUrl":"https://www.gutenberg.org/ebooks/1342","source":"Project Gutenberg / Gutendex","description":"Elizabeth Bennet and her four sisters grow up in a household where marriage is the great question of the future. She clashes with the proud Mr Darcy, whose first proposal is as arrogant as it is unexpected, while the charming Mr Wickham seems to offer a different kind of attention. Misjudgment and self-knowledge slowly clear the way for a truer understanding.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/20f69ce5c331427ef4daab9415231e31b1d9cfb2304f9a9e316a6728d62bee5d.jpg","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/bbd82efa5e3e8d8a302a39c5e20d7d6d250804c7003c63378946d85f1176ccb6.epub","fileSizeBytes":24835578,"contentHash":"bbd82efa5e3e8d8a302a39c5e20d7d6d250804c7003c63378946d85f1176ccb6","contentVersion":1,"isFeatured":true,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"license":"Public domain (Project Gutenberg)"}' WHERE id = 'gutenberg-1342';
UPDATE catalog SET data = '{"id":"gutenberg-145","title":"Middlemarch","author":"Eliot, George","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/fcdab17642ce67af0eb24836494879c300db5a833a4829f2920e99f373bb88a5.jpg","categoryId":"romance","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/6e49e3e85a0a0aecfc074366e287240b236bc262bdd2bbb35693ecac7af0a1e2.epub","fileSizeBytes":1072344,"contentVersion":1,"isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"language":"en","source":"gutendex","sourceId":145,"sourceUrl":"https://www.gutenberg.org/ebooks/145","rights":"PUBLIC_DOMAIN_US","downloadCount":85772,"subjects":["Bildungsromans","City and town life -- Fiction","Didactic fiction","Domestic fiction","England -- Fiction","Love stories","Married people -- Fiction","Young women -- Fiction"],"description":"Middlemarch follows the lives of several families in a provincial English town around the time of the Reform Bill. Dorothea Brooke marries the dry scholar Casaubon in search of a great purpose, while the doctor Tertius Lydgate tries to reform medicine and falls into debt. The novel traces ambition, marriage and compromise across a whole community.","contentHash":"6e49e3e85a0a0aecfc074366e287240b236bc262bdd2bbb35693ecac7af0a1e2","license":"Public domain (Project Gutenberg)"}' WHERE id = 'gutenberg-145';
UPDATE catalog SET data = '{"id":"gutenberg-1513","title":"Romeo and Juliet","author":"Shakespeare, William","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/90fc907ffc5a1d72209309d26c13daafb512a428a25d48c2293ba4c4eada0c2c.jpg","categoryId":"fiction","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/0dea6a849392a1e669f368f7ab7bd746fc4473418453fb956343ae297acf4412.epub","fileSizeBytes":341144,"contentVersion":1,"isFeatured":true,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"language":"en","source":"gutendex","sourceId":1513,"sourceUrl":"https://www.gutenberg.org/ebooks/1513","rights":"PUBLIC_DOMAIN_US","downloadCount":116214,"subjects":["Conflict of generations -- Drama","Juliet (Fictitious character) -- Drama","Romeo (Fictitious character) -- Drama","Tragedies (Drama)","Vendetta -- Drama","Verona (Italy) -- Drama","Youth -- Drama"],"description":"In Verona, Romeo Montague and Juliet Capulet meet at a feast and fall in love despite the feud between their families. They marry in secret, but a street fight and a failed plan drive them toward a tragic end. The play is a study of young love, haste and the cost of inherited hatred.","contentHash":"0dea6a849392a1e669f368f7ab7bd746fc4473418453fb956343ae297acf4412","license":"Public domain (Project Gutenberg)"}' WHERE id = 'gutenberg-1513';
