UPDATE catalog SET data = '{"id":"gutenberg-1727","title":"The Odyssey: Rendered into English prose for the use of those who cannot read the original","author":"Homer","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/be3607a8d2d3e97f0d49c27885dc94dd46aed200179cf2d72a8434c6608c56b2.jpg","categoryId":"fiction","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/bb40f821e2866690daafd8e5ca044b12f60c70ffd449ba2fe1b2a91fa76a9930.epub","fileSizeBytes":445840,"contentVersion":1,"isFeatured":true,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"language":"en","source":"gutendex","sourceId":1727,"sourceUrl":"https://www.gutenberg.org/ebooks/1727","rights":"PUBLIC_DOMAIN_US","downloadCount":120932,"subjects":["Epic poetry, Greek -- Translations into English","Homer -- Translations into English","Odysseus, King of Ithaca (Mythological character)"],"description":"The Odyssey follows Odysseus as he tries to return home to Ithaca after the Trojan War. His journey is delayed by monsters, enchantresses, storms and the anger of Poseidon, while his wife Penelope and son Telemachus wait under pressure from suitors. The poem is a foundational story of endurance, cunning and homecoming.","contentHash":"bb40f821e2866690daafd8e5ca044b12f60c70ffd449ba2fe1b2a91fa76a9930","license":"Public domain (Project Gutenberg)"}' WHERE id = 'gutenberg-1727';
UPDATE catalog SET data = '{"id":"gutenberg-17460","title":"Lorna Doone: A Romance of Exmoor","author":"Blackmore, R. D. (Richard Doddridge)","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/ab2230ef43f8652b70ed10983bf01c9001466de0df011f64ad5235703133ca90.jpg","categoryId":"romance","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/0b8edf92cacf13a08bfbb115d1b74fad7b4640aa5663feaa2f116dc9bb82195c.epub","fileSizeBytes":12322274,"contentVersion":1,"isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"language":"en","source":"gutendex","sourceId":17460,"sourceUrl":"https://www.gutenberg.org/ebooks/17460","rights":"PUBLIC_DOMAIN_US","downloadCount":77685,"subjects":["Exmoor (England) -- Fiction","Historical fiction","Love stories","Monmouth''s Rebellion, 1685 -- Fiction"],"description":"John Ridd, a farmer in Exmoor, falls in love with Lorna Doone, a young woman raised among the outlaw Doone family. Their love is complicated by the feud between the Doones and the surrounding communities, and by the secret of Lorna''s birth. The novel blends romance, local history and adventure in the West Country.","contentHash":"0b8edf92cacf13a08bfbb115d1b74fad7b4640aa5663feaa2f116dc9bb82195c","license":"Public domain (Project Gutenberg)"}' WHERE id = 'gutenberg-17460';
