UPDATE catalog SET data = '{"id":"gutenberg-20203","title":"Autobiography of Benjamin Franklin","author":"Franklin, Benjamin","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/d1a37ca0629f47a6c76f68ec3aff38598f5550f4acba8cfda1f23b0ae68f6dd1.jpg","categoryId":"history","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/6a24e47c32c36dc8dd845f51577d77eab58eaaa5226cdc2179249677e5e599f3.epub","fileSizeBytes":4914465,"contentVersion":1,"isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"language":"en","source":"gutendex","sourceId":20203,"sourceUrl":"https://www.gutenberg.org/ebooks/20203","rights":"PUBLIC_DOMAIN_US","downloadCount":76567,"subjects":["Franklin, Benjamin, 1706-1790","Statesmen -- United States -- Biography"],"description":"Benjamin Franklin recounts his rise from a printer''s apprentice in Boston to a leading figure in Philadelphia and the American Revolution. He describes his reading, his business, his experiments and his efforts at self-improvement. The book is a classic account of colonial American life and of a deliberate project of self-education.","contentHash":"6a24e47c32c36dc8dd845f51577d77eab58eaaa5226cdc2179249677e5e599f3","license":"Public domain (Project Gutenberg)"}' WHERE id = 'gutenberg-20203';
UPDATE catalog SET data = '{"id":"gutenberg-209","title":"The Turn of the Screw","author":"James, Henry","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/cc0db689a597402da7364bc17233851ee67e2f92d092b1e4617f2802ea7eb188.jpg","categoryId":"mystery","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/903346eb55a86d58d66401bbcec8bc1305314981fb38f102d6cacfbfa557d620.epub","fileSizeBytes":387516,"contentVersion":1,"isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"language":"en","source":"gutendex","sourceId":209,"sourceUrl":"https://www.gutenberg.org/ebooks/209","rights":"PUBLIC_DOMAIN_US","downloadCount":68373,"subjects":["Children -- Fiction","England -- Fiction","Ghost stories","Governesses -- Fiction","Psychological fiction"],"description":"A young governess takes charge of two children at a remote English estate and soon becomes convinced that the house is haunted. She believes the ghosts of a former valet and governess are corrupting the children, but no one else sees what she sees. The story is a famously ambiguous ghost tale about trust, repression and uncertainty.","contentHash":"903346eb55a86d58d66401bbcec8bc1305314981fb38f102d6cacfbfa557d620","license":"Public domain (Project Gutenberg)"}' WHERE id = 'gutenberg-209';
UPDATE catalog SET data = '{"id":"gutenberg-21839","title":"Sense and Sensibility","author":"Austen, Jane","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/7aae452e47822736abe189d330d5161b662f08bfa7f80173f2aabcb0ab8b9930.jpg","categoryId":"romance","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/7ae75f00fb2357e77a96bd95f40f2c34822d8360485028125d8ce150454e1e60.epub","fileSizeBytes":2109097,"contentVersion":1,"isFeatured":true,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"language":"en","source":"gutendex","sourceId":21839,"sourceUrl":"https://www.gutenberg.org/ebooks/21839","rights":"PUBLIC_DOMAIN_US","downloadCount":107602,"subjects":["Domestic fiction","England -- Fiction","England -- Social life and customs -- 19th century -- Fiction","Gentry -- England -- Fiction","Inheritance and succession -- Fiction","Love stories","Mate selection -- Fiction","Regency fiction","Sisters -- Fiction","Social classes -- Fiction","Young women -- Fiction"],"description":"Elinor and Marianne Dashwood lose their home and must live on a small income with their mother and younger sister. Elinor is cautious and hides her feelings, while Marianne is impulsive and romantic. Their experiences with love and disappointment test the balance between sense and sensibility.","contentHash":"7ae75f00fb2357e77a96bd95f40f2c34822d8360485028125d8ce150454e1e60","license":"Public domain (Project Gutenberg)"}' WHERE id = 'gutenberg-21839';
