UPDATE catalog SET data = '{"id":"gutenberg-32155","title":"The Love Letters of Henry VIII to Anne Boleyn; With Notes","author":"Henry VIII, King of England","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/9be1e19d1f27805c8bca54064540f00f70b69c139f7c71064eb29d520acd6453.png","categoryId":"history","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/7d69f5ea5f226dac77a21f327de3708756c2bb1175ef25ca50c1f151bac715ad.epub","fileSizeBytes":973512,"contentVersion":1,"isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"language":"en","source":"gutendex","sourceId":32155,"sourceUrl":"https://www.gutenberg.org/ebooks/32155","rights":"PUBLIC_DOMAIN_US","downloadCount":77027,"subjects":["Anne Boleyn, Queen, consort of Henry VIII, King of England, 1507-1536 -- Correspondence","Great Britain -- Kings and rulers -- Correspondence","Henry VIII, King of England, 1491-1547 -- Correspondence","Love-letters -- Early works to 1800"],"description":"This collection gathers the surviving letters Henry VIII wrote to Anne Boleyn before their marriage. They reveal the king''s courtship, his impatience and the political and religious crisis that followed his desire for an annulment. The letters are a primary source for one of the most consequential episodes in English history.","contentHash":"7d69f5ea5f226dac77a21f327de3708756c2bb1175ef25ca50c1f151bac715ad","license":"Public domain (Project Gutenberg)"}' WHERE id = 'gutenberg-32155';
