UPDATE catalog SET data = '{"id":"gutenberg-59828","title":"The String of Pearls; Or, The Barber of Fleet Street. A Domestic Romance.","author":"Prest, Thomas Peckett; Rymer, James Malcolm","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/c20671410eccaba147299b75936afddfd5321dc7ea79a87f4d2e452684b96717.jpg","categoryId":"mystery","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/ce48c244a8c38b082d51bf37acfe3a815a6435ce0fa0701c3646493b9fca495d.epub","fileSizeBytes":12357160,"contentVersion":1,"isFeatured":true,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"language":"en","source":"gutendex","sourceId":59828,"sourceUrl":"https://www.gutenberg.org/ebooks/59828","rights":"PUBLIC_DOMAIN_US","downloadCount":104191,"subjects":["Bakers -- Fiction","Barbers -- Fiction","Cannibalism -- Fiction","Fleet Street (London, England) -- Fiction","Historical fiction","Horror tales","London (England) -- Social life and customs -- 18th century -- Fiction","Missing persons -- Fiction","Murder -- Fiction","Mystery fiction","Penny dreadfuls","Revenge -- Fiction","Suspense fiction","Todd, Sweeney (Legendary character) -- Fiction","Young women -- Fiction"],"description":"This Victorian penny dreadful is the original tale of Sweeney Todd, a barber in Fleet Street who is suspected of murdering his customers. The story follows a young woman, Johanna, and the sailor Mark Ingestrie as they become entangled in Todd''s crimes. It is a melodrama of London streets, hidden identities and revenge.","contentHash":"ce48c244a8c38b082d51bf37acfe3a815a6435ce0fa0701c3646493b9fca495d","license":"Public domain (Project Gutenberg)"}' WHERE id = 'gutenberg-59828';
UPDATE catalog SET data = '{"id":"gutenberg-601","title":"The Monk: A Romance","author":"Lewis, M. G. (Matthew Gregory)","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/9d197ffb067185a693198e5bcb4e5fbaed8edcfb608e2e90d338198979046214.jpg","categoryId":"fiction","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/120b34d7a9f5464918c5cc8215a48025fd5ab010aa1ae7bc441b1c24e330d855.epub","fileSizeBytes":582872,"contentVersion":1,"isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"language":"en","source":"gutendex","sourceId":601,"sourceUrl":"https://www.gutenberg.org/ebooks/601","rights":"PUBLIC_DOMAIN_US","downloadCount":81058,"subjects":["Gothic fiction","Horror tales","Madrid (Spain) -- Fiction","Monks -- Fiction"],"description":"Ambrosio, a celebrated monk in Madrid, is admired for his piety but is gradually drawn into temptation by the demonic Matilda. His fall involves lust, murder and the supernatural, and the novel follows the ruin of several characters caught in his orbit. The Monk is a landmark of Gothic fiction, known for its intensity and transgression.","contentHash":"120b34d7a9f5464918c5cc8215a48025fd5ab010aa1ae7bc441b1c24e330d855","license":"Public domain (Project Gutenberg)"}' WHERE id = 'gutenberg-601';
UPDATE catalog SET data = '{"id":"gutenberg-70854","title":"The Countess of Pembroke''s Arcadia","author":"Sidney, Philip","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/184298a40ff9fe05dafbfb0f0dd6bba69b85d6f84290a5623f59dfa6cbc0890b.jpg","categoryId":"fiction","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/f5b97cd3c3120463d2ca901551320445888c995470ae5bc00b7cc49105de81c4.epub","fileSizeBytes":1056987,"contentVersion":1,"isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"language":"en","source":"gutendex","sourceId":70854,"sourceUrl":"https://www.gutenberg.org/ebooks/70854","rights":"PUBLIC_DOMAIN_US","downloadCount":74707,"subjects":["Pastoral literature, English"],"description":"Sir Philip Sidney''s Arcadia is a pastoral romance set in a fictional region of Greece, where princes and shepherds pursue love and adventure. The narrative weaves together disguises, oracles and political conflict in a highly patterned prose. It is one of the major works of Elizabethan literature and a model for later romance.","contentHash":"f5b97cd3c3120463d2ca901551320445888c995470ae5bc00b7cc49105de81c4","license":"Public domain (Project Gutenberg)"}' WHERE id = 'gutenberg-70854';
UPDATE catalog SET data = '{"id":"gutenberg-76","title":"Adventures of Huckleberry Finn","author":"Twain, Mark","language":"en","categoryId":"fiction","sourceUrl":"https://www.gutenberg.org/ebooks/76","source":"Project Gutenberg / Gutendex","description":"Huckleberry Finn runs away from his abusive father and travels down the Mississippi with Jim, an enslaved man who is escaping to freedom. Their raft journey brings them into contact with feuds, con men and the moral contradictions of the antebellum South. Huck''s growing loyalty to Jim forces him to question what society has taught him.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/8c3fed6a85de5d61881213933189663ac7ecb49b9a7ae1a2da2414ba910b400e.jpg","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/578224b814a7a9940456d622655525ed74ebf50e91fffd98484f4970d9cadcb8.epub","fileSizeBytes":16020333,"contentHash":"578224b814a7a9940456d622655525ed74ebf50e91fffd98484f4970d9cadcb8","contentVersion":1,"isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"license":"Public domain (Project Gutenberg)"}' WHERE id = 'gutenberg-76';
UPDATE catalog SET data = '{"id":"gutenberg-76639","title":"Eloisa: Or, a Series of Original Letters","author":"Rousseau, Jean-Jacques","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/a63291b1d634f8992d9ccfd8897d421339163fa74e4aac4b49e6a3dd320cb3e6.jpg","categoryId":"history","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/63b62f018470f5bb8bf7f5ada6137c7b75f922f8f6fd620205a8d5704913bee3.epub","fileSizeBytes":923740,"contentVersion":1,"isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"language":"en","source":"gutendex","sourceId":76639,"sourceUrl":"https://www.gutenberg.org/ebooks/76639","rights":"PUBLIC_DOMAIN_US","downloadCount":78866,"subjects":["Alps Region -- History -- 18th century -- Fiction","Epistolary fiction","French fiction -- Translations into English","Man-woman relationships -- Fiction","Psychological fiction","Women -- Fiction"],"description":"Rousseau''s Eloisa, or the New Heloise, is an epistolary novel about the love between the tutor Saint-Preux and his pupil Julie. Their passion is opposed by Julie''s family and by the demands of duty and reputation. The novel explores love, virtue and the conflict between feeling and social order.","contentHash":"63b62f018470f5bb8bf7f5ada6137c7b75f922f8f6fd620205a8d5704913bee3","license":"Public domain (Project Gutenberg)"}' WHERE id = 'gutenberg-76639';
UPDATE catalog SET data = '{"id":"gutenberg-84","title":"Frankenstein; or, the modern prometheus","author":"Shelley, Mary Wollstonecraft","language":"en","categoryId":"sci-fi","sourceUrl":"https://www.gutenberg.org/ebooks/84","source":"Project Gutenberg / Gutendex","description":"Victor Frankenstein, a young scientist, discovers the secret of giving life and creates a creature from assembled body parts. Horrified by his own work, he abandons the creature, who is left to learn about the world alone. The novel follows the consequences of that abandonment and the creature''s demand for recognition.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/8990ed8cec91ded006333f9f59af2f4496d25c70f9410aec85711bd9158a9ba0.jpg","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/2c29669a2cc1a726d6264178a2e8e86529208fd61ef92ca627b1612b2d98b2bd.epub","fileSizeBytes":474161,"contentHash":"2c29669a2cc1a726d6264178a2e8e86529208fd61ef92ca627b1612b2d98b2bd","contentVersion":1,"isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"license":"Public domain (Project Gutenberg)"}' WHERE id = 'gutenberg-84';
UPDATE catalog SET data = '{"id":"gutenberg-98","title":"A Tale of Two Cities","author":"Dickens, Charles","language":"en","categoryId":"fiction","sourceUrl":"https://www.gutenberg.org/ebooks/98","source":"Project Gutenberg / Gutendex","description":"The novel moves between London and Paris before and during the French Revolution. Charles Darnay, a French aristocrat living in England, is drawn back to Paris and condemned, while Sydney Carton, a dissolute lawyer, finds a chance to act selflessly. The story is about sacrifice, resurrection and the violence of history.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/2b33e199af692f3f8d293ee3981b5a2cf062c38b96237daa46fc6b8ed0d130fe.jpg","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/15701b1310e0c8cfb39162f803b126feefd8309c74707a63e1a32dbfe733af3f.epub","fileSizeBytes":7922028,"contentHash":"15701b1310e0c8cfb39162f803b126feefd8309c74707a63e1a32dbfe733af3f","contentVersion":1,"isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"license":"Public domain (Project Gutenberg)"}' WHERE id = 'gutenberg-98';
UPDATE catalog SET data = '{"id":"se-anna-sewell-black-beauty","title":"Black Beauty","author":"Anna Sewell","language":"en","categoryId":"fiction","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/27c4ed6cf6002e566930f4d4c252060b6f23eb15c59a62c598f61c2c1a195791.epub","fileSizeBytes":483392,"contentHash":"27c4ed6cf6002e566930f4d4c252060b6f23eb15c59a62c598f61c2c1a195791","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/anna-sewell/black-beauty","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Black Beauty is a horse''s first-person account of his life, beginning as a carefree foal on an English farm. Kind and cruel owners, stablemates and changing fortunes show how working horses were treated in Victorian England. The novel follows his journey through good homes and hard labour, and it argues for kindness and better treatment of animals.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/9c78b84f4fd3e72c23f3696a88888f4436bf37845e11eeb65711f280b505be45.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-anna-sewell-black-beauty';
UPDATE catalog SET data = '{"id":"se-arthur-conan-doyle-a-study-in-scarlet","title":"A Study in Scarlet","author":"Arthur Conan Doyle","language":"en","categoryId":"mystery","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/153b4fb5bdb6685a201e5dba568c7e2dc868943d06692cf700eb6589c1ee6695.epub","fileSizeBytes":616395,"contentHash":"153b4fb5bdb6685a201e5dba568c7e2dc868943d06692cf700eb6589c1ee6695","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/arthur-conan-doyle/a-study-in-scarlet","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Dr John Watson, newly returned from Afghanistan, meets the brilliant detective Sherlock Holmes and becomes his flatmate at 221B Baker Street. A corpse in an empty house and a cryptic message draw them into a murder investigation that baffles Scotland Yard. The trail leads through London and back to a story of love and revenge in the American West.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/928e3e106c7081da01b6014b4b4fe2dd807d180bcbcd2591d2bf263a30cde407.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-arthur-conan-doyle-a-study-in-scarlet';
UPDATE catalog SET data = '{"id":"se-arthur-conan-doyle-the-lost-world","title":"The Lost World","author":"Arthur Conan Doyle","language":"en","categoryId":"sci-fi","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/17cc20324af8c62faa3c122088e9d7d8fee606dfd85725c0555f03b14cd506c0.epub","fileSizeBytes":712491,"contentHash":"17cc20324af8c62faa3c122088e9d7d8fee606dfd85725c0555f03b14cd506c0","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/arthur-conan-doyle/the-lost-world","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Professor Challenger claims that dinosaurs still survive on a remote South American plateau, and a newspaper expedition sets out to prove him right. The party includes the sceptical Professor Summerlee and the reporter Edward Malone, who narrates. They find a land of prehistoric creatures and warring tribes, and must survive long enough to bring evidence home.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/9a0e5401b5f98578d17fae602d007ee2184470a41d5382a0fa7e89a590d5fbe7.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-arthur-conan-doyle-the-lost-world';
UPDATE catalog SET data = '{"id":"se-arthur-conan-doyle-the-sign-of-the-four","title":"The Sign of the Four","author":"Arthur Conan Doyle","language":"en","categoryId":"mystery","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/3b8f978721c0f290a3f703cde68573c63ed023131f8f4f206565e54faf704f76.epub","fileSizeBytes":884291,"contentHash":"3b8f978721c0f290a3f703cde68573c63ed023131f8f4f206565e54faf704f76","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/arthur-conan-doyle/the-sign-of-the-four","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Mary Morstan brings Sherlock Holmes a puzzle: her father vanished years ago, and she has since received pearls from an unknown sender. With Dr Watson, Holmes follows a trail of stolen treasure, a one-legged man and a secret pact made in colonial India. The case draws Watson closer to Mary and tests Holmes''s deductions.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/a6b1faaea5855e5419e2df9639cad9a672e792d99e1c59fa29488db6e684a6f7.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-arthur-conan-doyle-the-sign-of-the-four';
UPDATE catalog SET data = '{"id":"se-booker-t-washington-up-from-slavery","title":"Up from Slavery","author":"Booker T. Washington","language":"en","categoryId":"biography","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/55765cc004a12d9736867a4523b0ab5f52c655d838b6150e3414d13fd852c83f.epub","fileSizeBytes":656233,"contentHash":"55765cc004a12d9736867a4523b0ab5f52c655d838b6150e3414d13fd852c83f","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/booker-t-washington/up-from-slavery","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Booker T. Washington recounts his childhood in slavery, his struggle for education after emancipation, and his work building Tuskegee Institute. The memoir describes the daily realities of the post-Civil War South and his belief in self-help, industrial education and gradual progress. It is both a personal story and an argument about how Black Americans might advance in a hostile society.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/083b36cd6b6e7c0e450d994dcff6cb9fd754fb2f968fd104a283cb94c1c1a9e1.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-booker-t-washington-up-from-slavery';
UPDATE catalog SET data = '{"id":"se-charles-dickens-a-christmas-carol","title":"A Christmas Carol","author":"Charles Dickens","language":"en","categoryId":"fiction","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/89a365dbda5df107d37f026ff5879827d30e7ef14c40af19ca99730782eba276.epub","fileSizeBytes":548605,"contentHash":"89a365dbda5df107d37f026ff5879827d30e7ef14c40af19ca99730782eba276","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/charles-dickens/a-christmas-carol","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Ebenezer Scrooge is a cold, miserly London businessman who dismisses Christmas and everyone who celebrates it. On Christmas Eve he is visited by the ghost of his late partner and three spirits who show him his past, present and future. Confronted with the consequences of his life, Scrooge must decide whether to change before it is too late.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/ad7e51ca3f47e1247e4d3ebaf9fc2942a8887a5974d604801d49cbdbc8e760e1.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-charles-dickens-a-christmas-carol';
UPDATE catalog SET data = '{"id":"se-charles-dickens-bleak-house","title":"Bleak House","author":"Charles Dickens","language":"en","categoryId":"fiction","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/a83447996d1cf88ddb5c964ed8ed4e685899e1bc4ac78aa378aa10bccecabd76.epub","fileSizeBytes":1238504,"contentHash":"a83447996d1cf88ddb5c964ed8ed4e685899e1bc4ac78aa378aa10bccecabd76","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/charles-dickens/bleak-house","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Esther Summerson narrates much of this vast Victorian novel, which centres on a generations-long legal case, Jarndyce and Jarndyce. Around the lawsuit gather orphans, lawyers, philanthropists and the aristocratic Dedlocks, whose secrets reach across London and the countryside. Dickens satirises the courts and shows how the case damages nearly everyone it touches.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/c4c88677392e1a272358d3bcb87c6b5989860f9bf71a3698060c2ff320e12f54.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-charles-dickens-bleak-house';
UPDATE catalog SET data = '{"id":"se-charles-dickens-david-copperfield","title":"David Copperfield","author":"Charles Dickens","language":"en","categoryId":"fiction","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/1f328519d96750d6cd3449143eb33e91a55ae10eeb06509897bfa168896787e7.epub","fileSizeBytes":1373512,"contentHash":"1f328519d96750d6cd3449143eb33e91a55ae10eeb06509897bfa168896787e7","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/charles-dickens/david-copperfield","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"David Copperfield looks back on his life from childhood to adulthood, beginning with a happy early home that is broken by a cruel stepfather. He endures a brutal school, factory work and the loss of people he loves, while meeting characters such as the loyal Peggotty, the scheming Uriah Heep and the eccentric Mr Micawber. The novel follows his struggle to become a writer and to build a home of his own.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/4638c67205d6bed6db7b764571a23c98b992d995ef605361e7d47c6e1113aca7.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-charles-dickens-david-copperfield';
UPDATE catalog SET data = '{"id":"se-charles-dickens-great-expectations","title":"Great Expectations","author":"Charles Dickens","language":"en","categoryId":"fiction","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/9727f7ccd2d15c46de025fa3b164d3109ea56d3079946406fe2cad3b79a5990e.epub","fileSizeBytes":1002514,"contentHash":"9727f7ccd2d15c46de025fa3b164d3109ea56d3079946406fe2cad3b79a5990e","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/charles-dickens/great-expectations","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Philip Pirrip, called Pip, is a poor orphan raised by his sister and her kind husband, the blacksmith Joe Gargery. An encounter with an escaped convict and visits to the decaying house of Miss Havisham and the beautiful Estella fill him with shame about his background. When an unknown benefactor gives him money, Pip goes to London to become a gentleman, only to learn that his expectations rest on a dangerous secret.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/32e887c5755556f1d431a7bfcc2b5473eecc7de46d5e3003647cb19be684b27a.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-charles-dickens-great-expectations';
UPDATE catalog SET data = '{"id":"se-charles-dickens-hard-times","title":"Hard Times","author":"Charles Dickens","language":"en","categoryId":"fiction","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/b0837ea9bb5f9f16444c5983a0b182ea2777f851842e83b246925d998c94e626.epub","fileSizeBytes":984219,"contentHash":"b0837ea9bb5f9f16444c5983a0b182ea2777f851842e83b246925d998c94e626","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/charles-dickens/hard-times","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"In the industrial town of Coketown, Thomas Gradgrind raises his children on facts alone and dismisses imagination as useless. His daughter Louisa is pushed into a loveless marriage, while his son Tom drifts into crime and the workers struggle under mill owners. The novel follows the consequences of a philosophy that treats people as machines.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/da0c59a58bb47aee418e571855f7820c8e23fde5cb4499f96e138fdb3d8719cd.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-charles-dickens-hard-times';
