UPDATE catalog SET data = '{"id":"se-emily-bronte-wuthering-heights","title":"Wuthering Heights","author":"Emily Brontë","language":"en","categoryId":"romance","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/36cb7d44a2859d08a283a3c8c6f6205cc92fb398428440e8c40645b0c1882244.epub","fileSizeBytes":820456,"contentHash":"36cb7d44a2859d08a283a3c8c6f6205cc92fb398428440e8c40645b0c1882244","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/emily-bronte/wuthering-heights","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"The novel is framed by Mr Lockwood, who rents Thrushcross Grange and learns the history of the neighbouring Wuthering Heights. He hears how Heathcliff, an abandoned child taken in by the Earnshaw family, loved Catherine Earnshaw and was degraded after her brother''s cruelty. Their passion and the revenge it breeds shadow the next generation.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/cd23222400d731ec6b80107b9fc53f62177db76b2cb17e4309016b30874da1d3.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-emily-bronte-wuthering-heights';
UPDATE catalog SET data = '{"id":"se-frances-hodgson-burnett-the-secret-garden","title":"The Secret Garden","author":"Frances Hodgson Burnett","language":"en","categoryId":"fiction","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/fd8b90cf9033f6154c9bbeb861c01b18072f2710ce422a77d7807e36ae347325.epub","fileSizeBytes":623491,"contentHash":"fd8b90cf9033f6154c9bbeb861c01b18072f2710ce422a77d7807e36ae347325","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/frances-hodgson-burnett/the-secret-garden","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Mary Lennox, a sour child raised in colonial India, is sent to her uncle''s great house on the Yorkshire moors after her parents die. She discovers a walled garden that has been locked for years and, with a local boy named Dickon, begins to restore it. The work brings her and her sickly cousin Colin back to health and opens the house to life.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/6aa51c506a20706de7904f8f86c5ef7939eeae54c7c6ae89b97ce8fb7b369c6e.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-frances-hodgson-burnett-the-secret-garden';
UPDATE catalog SET data = '{"id":"se-frederick-douglass-narrative-of-the-life-of-frederick-douglass","title":"Narrative of the Life of Frederick Douglass","author":"Frederick Douglass","language":"en","categoryId":"biography","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/797cfb6fdebb77b000b10d2c6f33812800823f77a5a865590d356809db7917b3.epub","fileSizeBytes":416803,"contentHash":"797cfb6fdebb77b000b10d2c6f33812800823f77a5a865590d356809db7917b3","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/frederick-douglass/narrative-of-the-life-of-frederick-douglass","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Frederick Douglass recounts his birth into slavery in Maryland, his separation from his mother, and the brutality he witnessed and suffered. He describes how literacy and resistance changed him, including his fight with an overseer and his escape to the North. The narrative is both a personal testimony and a powerful argument against slavery.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/7225f478577ae93f1a3753f2c060667a6a1c4dede0fb6677de6ca6cc9b936030.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-frederick-douglass-narrative-of-the-life-of-frederick-douglass';
UPDATE catalog SET data = '{"id":"se-h-g-wells-the-invisible-man","title":"The Invisible Man","author":"H. G. Wells","language":"en","categoryId":"sci-fi","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/ea96500b18aeacca1a83c9f0689f411c3dc2feb2e76a81a22f3f0af66b318c46.epub","fileSizeBytes":680131,"contentHash":"ea96500b18aeacca1a83c9f0689f411c3dc2feb2e76a81a22f3f0af66b318c46","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/h-g-wells/the-invisible-man","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"A stranger wrapped in bandages arrives at a Sussex inn and keeps to himself, arousing suspicion among the villagers. He is Griffin, a scientist who has made himself invisible but cannot reverse the process, and his temper turns to violence. The story follows his increasingly desperate attempts to survive and the hunt that closes in on him.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/fbc396b798a7071f7d008917a4bbb698e7c0af3a96795fa1b130a4b0b58ed1c2.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-h-g-wells-the-invisible-man';
UPDATE catalog SET data = '{"id":"se-h-g-wells-the-island-of-doctor-moreau","title":"The Island of Doctor Moreau","author":"H. G. Wells","language":"en","categoryId":"sci-fi","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/f7b34cd4f130eb1c45ec7214f2e1821d251fcc74f585f07bf20711d2f31fe362.epub","fileSizeBytes":608590,"contentHash":"f7b34cd4f130eb1c45ec7214f2e1821d251fcc74f585f07bf20711d2f31fe362","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/h-g-wells/the-island-of-doctor-moreau","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Edward Prendick is rescued from a shipwreck and brought to a remote island owned by the physiologist Dr Moreau. There he discovers that Moreau performs cruel experiments on animals, shaping them into human-like creatures. Prendick must survive among the Beast Folk and confront what the doctor''s science has made.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/6224000b226e850c637d00d559d125e2328b803cc8cb46077d99696aa87ec9f9.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-h-g-wells-the-island-of-doctor-moreau';
