UPDATE catalog SET data = '{"id":"se-h-rider-haggard-she","title":"She","author":"H. Rider Haggard","language":"en","categoryId":"fiction","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/0cc628783ec873ca0187a31a2b0183be592f5218b4c299f281cea88f8ca357b6.epub","fileSizeBytes":1192532,"contentHash":"0cc628783ec873ca0187a31a2b0183be592f5218b4c299f281cea88f8ca357b6","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/h-rider-haggard/she","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Horace Holly and his ward Leo Vincey travel to Africa to follow an ancient family legend about a lost civilisation. They reach the kingdom of Kôr, ruled by Ayesha, a beautiful and terrifying woman who claims to have lived for centuries. Her power and her love for Leo drive the story toward its strange conclusion.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/c62ddbb3bb4bf9aaac0bb26d00fb0c32e67ae4056a2cddc3b88f5f48f1623073.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-h-rider-haggard-she';
UPDATE catalog SET data = '{"id":"se-henry-david-thoreau-walden","title":"Walden","author":"Henry David Thoreau","language":"en","categoryId":"biography","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/bfd95abe732c622cf2341abb2c1b78a8c7fdd19e43aebfd774dc7ffee1064fd4.epub","fileSizeBytes":997167,"contentHash":"bfd95abe732c622cf2341abb2c1b78a8c7fdd19e43aebfd774dc7ffee1064fd4","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/henry-david-thoreau/walden","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Henry David Thoreau describes the two years he spent living in a small cabin by Walden Pond, near Concord, Massachusetts. He writes about building the cabin, growing food, observing nature and simplifying his needs. The book is both a nature diary and an argument for self-reliance, attention and a life lived deliberately.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/2bd982f0b50edb1858299c92c896330eca6074ec615465484e8d279d7d4d1b6b.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-henry-david-thoreau-walden';
UPDATE catalog SET data = '{"id":"se-jack-london-the-call-of-the-wild","title":"The Call of the Wild","author":"Jack London","language":"en","categoryId":"fiction","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/dd29d33c8811128da6aba91cd9ba105c2fc939fc9a6b2881865ed29473df9d61.epub","fileSizeBytes":478502,"contentHash":"dd29d33c8811128da6aba91cd9ba105c2fc939fc9a6b2881865ed29473df9d61","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/jack-london/the-call-of-the-wild","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Buck, a large domestic dog, is stolen from a California ranch and sold into the Klondike gold rush. He learns to survive as a sled dog, enduring brutal work, changing masters and the rivalry of other dogs. Gradually his civilised habits fall away and the call of the wild grows stronger.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/aa96b3357cb2d97df6d9b1d35a0464c899e60827d267153e2c00cd9bd5d7c51e.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-jack-london-the-call-of-the-wild';
UPDATE catalog SET data = '{"id":"se-jack-london-white-fang","title":"White Fang","author":"Jack London","language":"en","categoryId":"fiction","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/2eca5bbc42ae023705f3dcc0ba5d0d0575c20dcf55917450b675fd5b2a812ea5.epub","fileSizeBytes":470501,"contentHash":"2eca5bbc42ae023705f3dcc0ba5d0d0575c20dcf55917450b675fd5b2a812ea5","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/jack-london/white-fang","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"White Fang is a wolf-dog born in the frozen North, where survival depends on strength and cunning. He passes from the wild to a Native American camp and then to a cruel white man who uses him in dogfights. A kind master, Weedon Scott, eventually tries to tame him and bring him into a gentler life.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/316ac3397020694cfd7570df79d4e1ba78dea5fc74c2460652d9271b824f3368.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-jack-london-white-fang';
UPDATE catalog SET data = '{"id":"se-jane-austen-emma","title":"Emma","author":"Jane Austen","language":"en","categoryId":"romance","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/05fa1677f0e842c68fb8ac98975e89aeafeee5b16f795b5047523575fa70ce2d.epub","fileSizeBytes":798853,"contentHash":"05fa1677f0e842c68fb8ac98975e89aeafeee5b16f795b5047523575fa70ce2d","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/jane-austen/emma","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Emma Woodhouse is clever, rich and convinced she knows what is best for everyone in her small English village. She takes on the matchmaking of her friend Harriet Smith, ignoring the warnings of her neighbour Mr Knightley. Her schemes produce misunderstandings and self-discovery before she learns where her own heart lies.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/7d40da96dd22c58be5e8f5c8829607531f1812a41b4407bba414a30c5f2ce5e2.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-jane-austen-emma';
UPDATE catalog SET data = '{"id":"se-jane-austen-mansfield-park","title":"Mansfield Park","author":"Jane Austen","language":"en","categoryId":"romance","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/ef870acb436392079e95a645402068d70308d2cd4cd4fa75f55cc9770bc9104f.epub","fileSizeBytes":708450,"contentHash":"ef870acb436392079e95a645402068d70308d2cd4cd4fa75f55cc9770bc9104f","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/jane-austen/mansfield-park","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Fanny Price is sent as a poor relation to live with her wealthy cousins at Mansfield Park. She grows up quiet and observant among the Bertram family, whose elegance hides selfishness and moral weakness. When the Crawford siblings arrive, Fanny must judge their charm and remain true to her own principles.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/1b2b02c611d8dbf96a18a8f375bbef18716e1d946df6e179db5601d46d259e28.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-jane-austen-mansfield-park';
UPDATE catalog SET data = '{"id":"se-jane-austen-northanger-abbey","title":"Northanger Abbey","author":"Jane Austen","language":"en","categoryId":"romance","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/637debd18edb3e105dfc57169a16ad70fa8406334871e4f12685e5082e31eef2.epub","fileSizeBytes":841951,"contentHash":"637debd18edb3e105dfc57169a16ad70fa8406334871e4f12685e5082e31eef2","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/jane-austen/northanger-abbey","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Catherine Morland, a young woman with a taste for Gothic novels, is invited to Bath and then to Northanger Abbey. She imagines intrigue and danger in the ordinary household of the Tilney family, and her fantasies lead to embarrassment. The novel gently mocks Gothic conventions while following Catherine''s growth into sense.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/e51600dc29a2142379856b02ae735e4f35a22a0fb6f1f9e00a09f29f8129bdcd.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-jane-austen-northanger-abbey';
UPDATE catalog SET data = '{"id":"se-jane-austen-persuasion","title":"Persuasion","author":"Jane Austen","language":"en","categoryId":"romance","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/d0040bd9c8d55d2693e26fa6fa3cad4f410a7bd13099e3085a62eaac6e0d5fc2.epub","fileSizeBytes":640478,"contentHash":"d0040bd9c8d55d2693e26fa6fa3cad4f410a7bd13099e3085a62eaac6e0d5fc2","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/jane-austen/persuasion","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Anne Elliot, the sensible daughter of a vain baronet, once refused a proposal from the naval officer Frederick Wentworth on the advice of her family. Years later, with the family in debt and Wentworth returned as a successful captain, they meet again. The novel follows Anne''s quiet endurance and the second chance she and Wentworth may have.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/690712c7a184cb32ee868cac5b2834bb4ad681f8ae109d0fe7256e389b119fb8.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-jane-austen-persuasion';
UPDATE catalog SET data = '{"id":"se-jonathan-swift-gullivers-travels","title":"Gulliver’s Travels","author":"Jonathan Swift","language":"en","categoryId":"fiction","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/cedf5daf17e8a8fd29a6dcdda02547c9c81965bc4ce5b7329d4218b2716c716c.epub","fileSizeBytes":1016600,"contentHash":"cedf5daf17e8a8fd29a6dcdda02547c9c81965bc4ce5b7329d4218b2716c716c","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/jonathan-swift/gullivers-travels","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Lemuel Gulliver, a ship''s surgeon, is shipwrecked and finds himself in a series of strange lands. He meets the tiny Lilliputians, the giant Brobdingnagians and the rational horses of Houyhnhnm land, among others. The travels are an adventure story and a satire of human pride, politics and reason.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/20bd6a5a82931a1769cbb445fa5aa2a77a57c10f43a4b50e622c38617d96c16e.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-jonathan-swift-gullivers-travels';
UPDATE catalog SET data = '{"id":"se-l-frank-baum-the-wonderful-wizard-of-oz","title":"The Wonderful Wizard of Oz","author":"L. Frank Baum","language":"en","categoryId":"fiction","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/5ddd1f98fd23d7abcfc209613afd9f1271bfbe825376a22fda6cbbc72e3a640a.epub","fileSizeBytes":681132,"contentHash":"5ddd1f98fd23d7abcfc209613afd9f1271bfbe825376a22fda6cbbc72e3a640a","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/l-frank-baum/the-wonderful-wizard-of-oz","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Dorothy Gale is carried by a cyclone from Kansas to the magical land of Oz, where she meets the Scarecrow, the Tin Woodman and the Cowardly Lion. They travel to the Emerald City to ask the Wizard for what each of them lacks. Their journey tests courage, kindness and the discovery that the power they seek may already be theirs.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/d4639c4caa35def9ffa64980829787476a0508ac91658ff0288f11637b31314a.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-l-frank-baum-the-wonderful-wizard-of-oz';
UPDATE catalog SET data = '{"id":"se-l-m-montgomery-anne-of-green-gables","title":"Anne of Green Gables","author":"L. M. Montgomery","language":"en","categoryId":"fiction","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/f8ebee78f47ae986a2792846c0ad0732b1a13cdceda4b1a358c454bff71d1eea.epub","fileSizeBytes":1087353,"contentHash":"f8ebee78f47ae986a2792846c0ad0732b1a13cdceda4b1a358c454bff71d1eea","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/l-m-montgomery/anne-of-green-gables","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Matthew and Marilla Cuthbert intend to adopt a boy to help on their farm in Avonlea, but a mix-up brings them the talkative orphan Anne Shirley. Anne''s imagination and temper disrupt the quiet household and win over the community. The novel follows her education, friendships and growing sense of belonging.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/289f1f40b57c818b883cc47c4f28a9a1317050ca6f7c7d67c48a2bed37188007.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-l-m-montgomery-anne-of-green-gables';
UPDATE catalog SET data = '{"id":"se-mark-twain-the-adventures-of-tom-sawyer","title":"The Adventures of Tom Sawyer","author":"Mark Twain","language":"en","categoryId":"fiction","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/6d9a36a71c755a7ae40c55518666ba924a5be130dc1fc09b173f5028475526c2.epub","fileSizeBytes":697383,"contentHash":"6d9a36a71c755a7ae40c55518666ba924a5be130dc1fc09b173f5028475526c2","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/mark-twain/the-adventures-of-tom-sawyer","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Tom Sawyer grows up in the fictional town of St Petersburg on the Mississippi, skipping school and chasing adventure with his friends. He witnesses a midnight murder, runs away to an island and attends his own funeral. The novel mixes comedy and danger as Tom learns about responsibility and the adult world.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/7e07ab8c7aafcaa9b926338ea69965c2097a48bc2a734066f8e4772039b0166e.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-mark-twain-the-adventures-of-tom-sawyer';
UPDATE catalog SET data = '{"id":"se-nathaniel-hawthorne-the-scarlet-letter","title":"The Scarlet Letter","author":"Nathaniel Hawthorne","language":"en","categoryId":"fiction","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/f08c8e08deb9a147441e85140445d2368b6fcdbbd308926df0818b0f094f4568.epub","fileSizeBytes":554814,"contentHash":"f08c8e08deb9a147441e85140445d2368b6fcdbbd308926df0818b0f094f4568","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/nathaniel-hawthorne/the-scarlet-letter","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Hester Prynne is condemned to wear a scarlet letter A after bearing a child out of wedlock in Puritan Boston. She refuses to name the father, the minister Arthur Dimmesdale, who is consumed by hidden guilt. The novel explores shame, hypocrisy and the cost of secrets in a rigid community.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/8e0de89fcb712bea434a621e2b7f3d3063e0ab7c01fe0c52bbbbdff7757d3792.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-nathaniel-hawthorne-the-scarlet-letter';
UPDATE catalog SET data = '{"id":"se-oscar-wilde-the-picture-of-dorian-gray","title":"The Picture of Dorian Gray","author":"Oscar Wilde","language":"en","categoryId":"fiction","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/11cee02b0cb5836ea3afdddba89e3cdeca88b933285153b5fe84b8f9fe09bce6.epub","fileSizeBytes":634140,"contentHash":"11cee02b0cb5836ea3afdddba89e3cdeca88b933285153b5fe84b8f9fe09bce6","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/oscar-wilde/the-picture-of-dorian-gray","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Dorian Gray, a beautiful young man, sits for a portrait by the artist Basil Hallward and is persuaded by Lord Henry Wotton that youth and pleasure are all that matter. He wishes the portrait would age instead of him, and the wish comes true. As Dorian''s life becomes cruel and corrupt, the painting records the damage.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/8e31eab93ce84dc5c79a6fed2661c7ccaecf05fc3aca64d0eab499f24e90991b.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-oscar-wilde-the-picture-of-dorian-gray';
UPDATE catalog SET data = '{"id":"se-rudyard-kipling-kim","title":"Kim","author":"Rudyard Kipling","language":"en","categoryId":"fiction","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/ba0fa5b33f0e2d1daad246541f1545f9c41a4624f9b034d706c30a91a4fe92c6.epub","fileSizeBytes":848312,"contentHash":"ba0fa5b33f0e2d1daad246541f1545f9c41a4624f9b034d706c30a91a4fe92c6","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/rudyard-kipling/kim","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Kimball O''Hara, an orphaned Irish boy, grows up on the streets of Lahore and becomes involved in the Great Game of imperial intelligence. He travels with a Tibetan lama while also working for British agents. The novel follows his education, his loyalty to the lama and his place between two worlds.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/be100b45969f35dcb28afea0770ddcaf437c3d9829b91884ff7d6163e2ed844a.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-rudyard-kipling-kim';
UPDATE catalog SET data = '{"id":"se-rudyard-kipling-the-jungle-book","title":"The Jungle Book","author":"Rudyard Kipling","language":"en","categoryId":"fiction","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/301cfaf849755dacaf90536d3c240005ed8212cea25b167e2c501e72fc523184.epub","fileSizeBytes":599536,"contentHash":"301cfaf849755dacaf90536d3c240005ed8212cea25b167e2c501e72fc523184","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/rudyard-kipling/the-jungle-book","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Mowgli, a boy raised by wolves in the Indian jungle, learns the law of the jungle from Baloo the bear and Bagheera the panther. He faces the tiger Shere Khan and the monkey people, and must decide where he belongs. The collection also includes stories of other animals and the world beyond the jungle.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/652016d875d46c64d1ac2ff133fb59220b568d05a9f128d946b6303ad23dccfa.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-rudyard-kipling-the-jungle-book';
UPDATE catalog SET data = '{"id":"se-stephen-crane-the-red-badge-of-courage","title":"The Red Badge of Courage","author":"Stephen Crane","language":"en","categoryId":"fiction","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/837f73c40c66262c2e9a0f660d776c8d59094eb5677b423a3c019a814cd3f818.epub","fileSizeBytes":758461,"contentHash":"837f73c40c66262c2e9a0f660d776c8d59094eb5677b423a3c019a814cd3f818","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/stephen-crane/the-red-badge-of-courage","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Henry Fleming, a young Union soldier, dreams of glory and enlists in the American Civil War. When the fighting comes, fear overwhelms him and he flees, then struggles with shame and the desire for a wound that would prove his courage. The novel follows his return to the regiment and his changing understanding of bravery.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/b68a40428e37ee712d868973719291d062f39f1203bcdaeb722f2decd2863821.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-stephen-crane-the-red-badge-of-courage';
UPDATE catalog SET data = '{"id":"se-thomas-hardy-far-from-the-madding-crowd","title":"Far from the Madding Crowd","author":"Thomas Hardy","language":"en","categoryId":"romance","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/a73f37347769e83b501bf25bd96e2b31102fe4c24d30f29c90f8bef6e5637579.epub","fileSizeBytes":1025553,"contentHash":"a73f37347769e83b501bf25bd96e2b31102fe4c24d30f29c90f8bef6e5637579","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/thomas-hardy/far-from-the-madding-crowd","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Bathsheba Everdene inherits a farm in Wessex and becomes the object of three very different suitors. Gabriel Oak, a shepherd, loves her steadily; the wealthy Boldwood is obsessive; and the soldier Sergeant Troy is reckless. The novel follows Bathsheba''s choices and the consequences for the people around her.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/79aacfe269b9aa759535c0f4cdf65787e1844b2a2824515b9b4cd8e1c89c8c8b.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-thomas-hardy-far-from-the-madding-crowd';
UPDATE catalog SET data = '{"id":"se-thomas-hardy-tess-of-the-durbervilles","title":"Tess of the d’Urbervilles","author":"Thomas Hardy","language":"en","categoryId":"romance","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/6e32181fbfaaf1a626bc1804ed2120c07c4b2fc706136d9bc56f55ed050aae9e.epub","fileSizeBytes":1140305,"contentHash":"6e32181fbfaaf1a626bc1804ed2120c07c4b2fc706136d9bc56f55ed050aae9e","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/thomas-hardy/tess-of-the-durbervilles","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Tess Durbeyfield, the daughter of a poor rural family, is sent to claim kinship with the wealthy d''Urbervilles. There she meets Alec d''Urberville, whose attentions change her life, and later the idealistic Angel Clare. The novel follows Tess''s struggle against social judgment and the double standard that punishes her.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/74bb7a458558f178c6a5d7e44b10573384b4c80776f5c52be0f67fec1b6c31dc.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-thomas-hardy-tess-of-the-durbervilles';
UPDATE catalog SET data = '{"id":"se-wilkie-collins-the-moonstone","title":"The Moonstone","author":"Wilkie Collins","language":"en","categoryId":"mystery","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/a62a2002f2fb13e5e90cc89f0210d8355a8252fb83c1dc9f1c0ca76bc4b3cc4e.epub","fileSizeBytes":958053,"contentHash":"a62a2002f2fb13e5e90cc89f0210d8355a8252fb83c1dc9f1c0ca76bc4b3cc4e","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/wilkie-collins/the-moonstone","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"A large diamond brought from India is given to Rachel Verinder on her birthday and vanishes the same night. The household is thrown into confusion, and the mystery is told through several witnesses, including the servant Gabriel Betteredge and the detective Sergeant Cuff. The novel follows the diamond''s history and the secrets behind its theft.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/4139eaea2262ce94b3842ee69fd3695d75f26bbfef6c7058e995494ea9a622c7.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-wilkie-collins-the-moonstone';
UPDATE catalog SET data = '{"id":"se-wilkie-collins-the-woman-in-white","title":"The Woman in White","author":"Wilkie Collins","language":"en","categoryId":"mystery","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/c6e53a06cce709236403de27d62230b65392de94e8841d01a681917390f0ed88.epub","fileSizeBytes":1162016,"contentHash":"c6e53a06cce709236403de27d62230b65392de94e8841d01a681917390f0ed88","contentVersion":1,"source":"Standard Ebooks","sourceUrl":"https://standardebooks.org/ebooks/wilkie-collins/the-woman-in-white","rights":"PUBLIC_DOMAIN_US","rightsUrl":"https://standardebooks.org/about/standard-ebooks-and-the-public-domain","editionLicense":"CC0-1.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Walter Hartright, a drawing teacher, meets a mysterious woman dressed in white on a lonely road and learns that she has escaped from an asylum. He later becomes involved with the family at Limmeridge House and discovers a conspiracy involving identity, inheritance and a dangerous secret. The novel is told through multiple narrators and documents.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/15a1198f55609c27b8cc16f3f862146564b8c825011edaed5fe60de3fc5778f8.jpg","license":"Public domain; edition contributions CC0 1.0"}' WHERE id = 'se-wilkie-collins-the-woman-in-white';
UPDATE catalog SET data = '{"id":"ws-vi-binh-ngo-dai-cao","title":"Bình Ngô đại cáo","author":"Nguyễn Trãi","language":"vi","categoryId":"history","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/04c7dc36f022e4db0fbea8906df61b0da2fd57532b2f8e91d2ea7b7e3a0bc46d.epub","fileSizeBytes":11045,"contentHash":"04c7dc36f022e4db0fbea8906df61b0da2fd57532b2f8e91d2ea7b7e3a0bc46d","contentVersion":1,"source":"Wikisource tiếng Việt","sourceUrl":"https://vi.wikisource.org/wiki/B%C3%ACnh_Ng%C3%B4_%C4%91%E1%BA%A1i_c%C3%A1o","rights":"PUBLIC_DOMAIN_VN","rightsUrl":"https://vi.wikisource.org/wiki/Wikisource:Quy_%C4%91%E1%BB%8Bnh_b%E1%BA%A3n_quy%E1%BB%81n","editionLicense":"CC-BY-SA-4.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Bình Ngô đại cáo là áng văn chính luận Nguyễn Trãi viết thay lời Lê Lợi sau khi đánh thắng quân Minh. Tác phẩm nêu tư tưởng nhân nghĩa, kể lại tội ác của giặc và quá trình khởi nghĩa Lam Sơn. Phần cuối tuyên bố nền hòa bình và khẳng định chủ quyền, truyền thống văn hiến của Đại Việt.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/9c555bfd9320db02ddefa88432e12038d17cd81d00d5ca041096444ac30c94d5.jpg","license":"Phạm vi công cộng (Wikisource)"}' WHERE id = 'ws-vi-binh-ngo-dai-cao';
UPDATE catalog SET data = '{"id":"ws-vi-chinh-phu-ngam","title":"Chinh phụ ngâm","author":"Đặng Trần Côn; Đoàn Thị Điểm","language":"vi","categoryId":"poetry","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/098df4d0421622f4555e1495ba4fed665f465bda8921a78b5b8f4d21ea1ac73d.epub","fileSizeBytes":18413,"contentHash":"098df4d0421622f4555e1495ba4fed665f465bda8921a78b5b8f4d21ea1ac73d","contentVersion":1,"source":"Wikisource tiếng Việt","sourceUrl":"https://vi.wikisource.org/wiki/Chinh_ph%E1%BB%A5_ng%C3%A2m","rights":"PUBLIC_DOMAIN_VN","rightsUrl":"https://vi.wikisource.org/wiki/Wikisource:Quy_%C4%91%E1%BB%8Bnh_b%E1%BA%A3n_quy%E1%BB%81n","editionLicense":"CC-BY-SA-4.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Chinh phụ ngâm là khúc ngâm dài viết bằng chữ Hán, bản diễn Nôm nổi tiếng của Đoàn Thị Điểm. Tác phẩm thể hiện nỗi sầu của người vợ có chồng ra trận, từ lúc tiễn biệt đến những năm tháng cô đơn. Qua nỗi nhớ và cảnh chờ đợi, tác phẩm lên án chiến tranh phi nghĩa và khát vọng hạnh phúc lứa đôi.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/f2c25537cfd927391b1c8f68292b80324909daf93145cc0bc4d83b58fdb18c0b.jpg","license":"Phạm vi công cộng (Wikisource)"}' WHERE id = 'ws-vi-chinh-phu-ngam';
UPDATE catalog SET data = '{"id":"ws-vi-cung-oan-ngam-khuc","title":"Cung oán ngâm khúc","author":"Nguyễn Gia Thiều","language":"vi","categoryId":"poetry","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/368aa1ecb180321c7df641b5ff5d1105ca50648f6290b3814ecc0863e54aeb11.epub","fileSizeBytes":18045,"contentHash":"368aa1ecb180321c7df641b5ff5d1105ca50648f6290b3814ecc0863e54aeb11","contentVersion":1,"source":"Wikisource tiếng Việt","sourceUrl":"https://vi.wikisource.org/wiki/Cung_o%C3%A1n_ng%C3%A2m_kh%C3%BAc_%28b%E1%BA%A3n_Edmond_Nordemann_1905%29","rights":"PUBLIC_DOMAIN_VN","rightsUrl":"https://vi.wikisource.org/wiki/Wikisource:Quy_%C4%91%E1%BB%8Bnh_b%E1%BA%A3n_quy%E1%BB%81n","editionLicense":"CC-BY-SA-4.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Cung oán ngâm khúc là khúc ngâm viết bằng chữ Nôm của Nguyễn Gia Thiều. Tác phẩm mượn lời một cung nữ tài sắc bị thất sủng để nói về nỗi cô đơn, phai tàn và sự bất công trong chốn cung đình. Qua đó, tác giả gửi gắm nỗi xót xa cho thân phận con người và phê phán chế độ cung tần.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/c8e2f32b58f7601cead087ae37e81bc3c7a0d59d417c521747bce5b982a77660.jpg","license":"Phạm vi công cộng (Wikisource)"}' WHERE id = 'ws-vi-cung-oan-ngam-khuc';
UPDATE catalog SET data = '{"id":"ws-vi-dai-nam-quoc-su-dien-ca","title":"Đại Nam Quốc sử Diễn ca","author":"Lê Ngô Cát; Phạm Đình Toái","language":"vi","categoryId":"history","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/742dd837d1ea5366e32827a6e6ac4d7710ff077ad9f24dee092b6a355dfc9544.epub","fileSizeBytes":46103,"contentHash":"742dd837d1ea5366e32827a6e6ac4d7710ff077ad9f24dee092b6a355dfc9544","contentVersion":1,"source":"Wikisource tiếng Việt","sourceUrl":"https://vi.wikisource.org/wiki/%C4%90%E1%BA%A1i_Nam_Qu%E1%BB%91c_s%E1%BB%AD_Di%E1%BB%85n_ca","rights":"PUBLIC_DOMAIN_VN","rightsUrl":"https://vi.wikisource.org/wiki/Wikisource:Quy_%C4%91%E1%BB%8Bnh_b%E1%BA%A3n_quy%E1%BB%81n","editionLicense":"CC-BY-SA-4.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Đại Nam Quốc sử Diễn ca là bộ sử ca do Lê Ngô Cát soạn, Phạm Đình Toái nhuận sắc. Tác phẩm kể lịch sử Việt Nam từ thời Hồng Bàng đến đầu triều Nguyễn bằng thể lục bát. Nội dung khái quát các triều đại, nhân vật và sự kiện lớn, nhằm giáo dục lòng yêu nước và hiểu biết lịch sử.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/32199c0ac658928a7409eb27b2ae7f5e4f25c98f6b390790d76ac8135cabe360.jpg","license":"Phạm vi công cộng (Wikisource)"}' WHERE id = 'ws-vi-dai-nam-quoc-su-dien-ca';
UPDATE catalog SET data = '{"id":"ws-vi-dai-viet-su-ky","title":"Đại Việt sử ký toàn thư","author":"Ngô Sĩ Liên","language":"vi","categoryId":"history","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/4c9c9f970b76a965d724b6cae5e43eb7caf0113d7edb9f444f9c707416c25b26.epub","fileSizeBytes":155864,"contentHash":"4c9c9f970b76a965d724b6cae5e43eb7caf0113d7edb9f444f9c707416c25b26","contentVersion":1,"source":"Wikisource tiếng Việt","sourceUrl":"https://vi.wikisource.org/wiki/%C4%90%E1%BA%A1i_Vi%E1%BB%87t_s%E1%BB%AD_k%C3%BD_to%C3%A0n_th%C6%B0","rights":"PUBLIC_DOMAIN_VN","rightsUrl":"https://vi.wikisource.org/wiki/Wikisource:Quy_%C4%91%E1%BB%8Bnh_b%E1%BA%A3n_quy%E1%BB%81n","editionLicense":"CC-BY-SA-4.0","isFeatured":true,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Đại Việt sử ký toàn thư là bộ chính sử lớn của Việt Nam, do Ngô Sĩ Liên và các sử gia triều Lê biên soạn. Tác phẩm ghi chép lịch sử Đại Việt từ thời dựng nước đến thế kỷ XV, theo thể biên niên. Đây là nguồn tư liệu quan trọng về các triều đại, chính trị, quân sự và văn hóa.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/c31b0018612abb7fb83d5d0230fa3c7fc6b56fc7529e12a2173c915cf3a63579.jpg","license":"Phạm vi công cộng (Wikisource)"}' WHERE id = 'ws-vi-dai-viet-su-ky';
UPDATE catalog SET data = '{"id":"ws-vi-doi-cach-mang-phan-boi-chau","title":"Đời cách mạng Phan Bội Châu","author":"Phan Bội Châu","language":"vi","categoryId":"biography","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/33969ed2768f5639b126e35c9331c14d4a9d74ca4e790d78cfb45dd02f14630a.epub","fileSizeBytes":85977,"contentHash":"33969ed2768f5639b126e35c9331c14d4a9d74ca4e790d78cfb45dd02f14630a","contentVersion":1,"source":"Wikisource tiếng Việt","sourceUrl":"https://vi.wikisource.org/wiki/%C4%90%E1%BB%9Di_c%C3%A1ch_m%E1%BA%A1ng_Phan_B%E1%BB%99i_Ch%C3%A2u","rights":"PUBLIC_DOMAIN_VN","rightsUrl":"https://vi.wikisource.org/wiki/Wikisource:Quy_%C4%91%E1%BB%8Bnh_b%E1%BA%A3n_quy%E1%BB%81n","editionLicense":"CC-BY-SA-4.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Đời cách mạng Phan Bội Châu là hồi ký của nhà chí sĩ yêu nước Phan Bội Châu. Tác phẩm kể lại cuộc đời hoạt động cách mạng của ông, từ phong trào Duy Tân, Đông Du đến những năm tháng bị giam lỏng. Qua đó, người đọc hiểu thêm về lịch sử Việt Nam đầu thế kỷ XX và tinh thần yêu nước của một thế hệ.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/132694f50b5afed781cd71a021bfdcb122e9825ea957198f40cc23fbe6737fc5.jpg","license":"Phạm vi công cộng (Wikisource)"}' WHERE id = 'ws-vi-doi-cach-mang-phan-boi-chau';
UPDATE catalog SET data = '{"id":"ws-vi-hoang-le-nhat-thong-chi","title":"Hoàng Lê nhất thống chí","author":"Ngô gia văn phái","language":"vi","categoryId":"history","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/2f16f8f9408a175dd1c7ecacc5efdd4a2a7b19385815d6aeb9b431e41890b6d4.epub","fileSizeBytes":291205,"contentHash":"2f16f8f9408a175dd1c7ecacc5efdd4a2a7b19385815d6aeb9b431e41890b6d4","contentVersion":1,"source":"Wikisource tiếng Việt","sourceUrl":"https://vi.wikisource.org/wiki/Ho%C3%A0ng_L%C3%AA_nh%E1%BA%A5t_th%E1%BB%91ng_ch%C3%AD","rights":"PUBLIC_DOMAIN_VN","rightsUrl":"https://vi.wikisource.org/wiki/Wikisource:Quy_%C4%91%E1%BB%8Bnh_b%E1%BA%A3n_quy%E1%BB%81n","editionLicense":"CC-BY-SA-4.0","isFeatured":true,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Hoàng Lê nhất thống chí là tiểu thuyết lịch sử của nhóm Ngô gia văn phái. Tác phẩm ghi lại giai đoạn cuối triều Lê, sự nổi dậy của Tây Sơn và chiến thắng Ngọc Hồi – Đống Đa của vua Quang Trung. Tác phẩm khắc họa nhiều nhân vật lịch sử và phản ánh những biến động chính trị thời bấy giờ.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/40aeffbe41c3b5a53f7e08ea4204d4b1a34b78236514df16b304c7ca71b65a05.jpg","license":"Phạm vi công cộng (Wikisource)"}' WHERE id = 'ws-vi-hoang-le-nhat-thong-chi';
UPDATE catalog SET data = '{"id":"ws-vi-kieu","title":"Truyện Kiều","author":"Nguyễn Du","language":"vi","categoryId":"fiction","sourceUrl":"https://vi.wikisource.org/wiki/Truy%E1%BB%87n%20Ki%E1%BB%81u","source":"Wikisource tiếng Việt","description":"Truyện Kiều là truyện thơ Nôm bất hủ của Nguyễn Du, dựa trên tiểu thuyết Kim Vân Kiều truyện của Thanh Tâm Tài Nhân. Tác phẩm kể cuộc đời Thúy Kiều, một người con gái tài sắc phải bán mình cứu gia đình và chịu nhiều bất hạnh. Qua số phận Kiều, Nguyễn Du gửi gắm nỗi thương cảm cho con người và những trăn trở về tài, mệnh, tình yêu và công lý.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/eddde6285458c24c2a4cff00d05d05b95511c8be22a73904f95327bbd6493eab.jpg","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/4fc8bc6cf2df378da046c666ce8154ce062c0b9e4231d2602648b916a8d5c9ec.epub","fileSizeBytes":62922,"contentHash":"4fc8bc6cf2df378da046c666ce8154ce062c0b9e4231d2602648b916a8d5c9ec","contentVersion":1,"isFeatured":true,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"license":"Phạm vi công cộng (Wikisource)"}' WHERE id = 'ws-vi-kieu';
UPDATE catalog SET data = '{"id":"ws-vi-luc-van-tien","title":"Lục Vân Tiên","author":"Nguyễn Đình Chiểu","language":"vi","categoryId":"fiction","sourceUrl":"https://vi.wikisource.org/wiki/L%E1%BB%A5c%20V%C3%A2n%20Ti%C3%AAn%20%28b%E1%BA%A3n%20Qu%E1%BB%91c%20ng%E1%BB%AF%202082%20c%C3%A2u%29","source":"Wikisource tiếng Việt","description":"Lục Vân Tiên là truyện thơ Nôm của Nguyễn Đình Chiểu, kể về chàng thư sinh Lục Vân Tiên. Trên đường về kinh thi, chàng đánh cướp cứu Kiều Nguyệt Nga rồi gặp nhiều thử thách, chia ly và hiểu lầm. Tác phẩm đề cao nghĩa khí, lòng trung hiếu và tinh thần nhân nghĩa của con người.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/2380d160e5c6db79475b012c0f1af5e9f88877893c5ac23369350a50a02b37a1.jpg","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/d70a9c1443ee0bfb0cb1070d695a8260f7b5812185dfe0e67382bcd4c7d4fd07.epub","fileSizeBytes":65278,"contentHash":"d70a9c1443ee0bfb0cb1070d695a8260f7b5812185dfe0e67382bcd4c7d4fd07","contentVersion":1,"isFeatured":true,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"license":"Phạm vi công cộng (Wikisource)"}' WHERE id = 'ws-vi-luc-van-tien';
UPDATE catalog SET data = '{"id":"ws-vi-nam-hai-di-nhan","title":"Nam Hải dị nhân liệt truyện","author":"Phan Kế Bính","language":"vi","categoryId":"fiction","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/3f6dd3f93790d7070f66df9aedb783376595172534a59bf745640e672cf367f6.epub","fileSizeBytes":231745,"contentHash":"3f6dd3f93790d7070f66df9aedb783376595172534a59bf745640e672cf367f6","contentVersion":1,"source":"Wikisource tiếng Việt","sourceUrl":"https://vi.wikisource.org/wiki/Nam_H%E1%BA%A3i_d%E1%BB%8B_nh%C3%A2n_li%E1%BB%87t_truy%E1%BB%87n","rights":"PUBLIC_DOMAIN_VN","rightsUrl":"https://vi.wikisource.org/wiki/Wikisource:Quy_%C4%91%E1%BB%8Bnh_b%E1%BA%A3n_quy%E1%BB%81n","editionLicense":"CC-BY-SA-4.0","isFeatured":true,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Nam Hải dị nhân liệt truyện là tập truyện ký của Phan Kế Bính, ghi chép về những nhân vật kỳ lạ và truyền thuyết dân gian Việt Nam. Tác phẩm tập hợp các câu chuyện về người tài, chuyện lạ và những hiện tượng dị thường. Đây là tư liệu văn hóa dân gian quý, phản ánh tín ngưỡng và trí tưởng tượng của người Việt.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/93640d31985a462ac538dba76d20a6955ed5a51373298a317c4b75856e0d592d.jpg","license":"Phạm vi công cộng (Wikisource)"}' WHERE id = 'ws-vi-nam-hai-di-nhan';
UPDATE catalog SET data = '{"id":"ws-vi-ngu-tieu-y-thuat","title":"Ngư Tiều y thuật vấn đáp","author":"Nguyễn Đình Chiểu","language":"vi","categoryId":"fiction","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/a4d89d5859a387043e5510659c36b018d1784e0c8c85a6bb074d3b24262a103e.epub","fileSizeBytes":84655,"contentHash":"a4d89d5859a387043e5510659c36b018d1784e0c8c85a6bb074d3b24262a103e","contentVersion":1,"source":"Wikisource tiếng Việt","sourceUrl":"https://vi.wikisource.org/wiki/Ng%C6%B0_Ti%E1%BB%81u_y_thu%E1%BA%ADt_v%E1%BA%A5n_%C4%91%C3%A1p","rights":"PUBLIC_DOMAIN_VN","rightsUrl":"https://vi.wikisource.org/wiki/Wikisource:Quy_%C4%91%E1%BB%8Bnh_b%E1%BA%A3n_quy%E1%BB%81n","editionLicense":"CC-BY-SA-4.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Ngư Tiều y thuật vấn đáp là tác phẩm của Nguyễn Đình Chiểu, viết dưới hình thức đối thoại giữa người đánh cá và người tiều phu. Nội dung bàn về y thuật, đạo làm người và cách chữa bệnh, chăm sóc sức khỏe. Tác phẩm thể hiện tấm lòng thương người và kiến thức y học của tác giả.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/411f33ec7a6cb56f9c40924b8da8d47ae40559bd1a4b01fb2b2ece1a0a4b04d9.jpg","license":"Phạm vi công cộng (Wikisource)"}' WHERE id = 'ws-vi-ngu-tieu-y-thuat';
UPDATE catalog SET data = '{"id":"ws-vi-tho-ho-xuan-huong","title":"Thơ Hồ Xuân Hương","author":"Hồ Xuân Hương","language":"vi","categoryId":"poetry","format":"EPUB","fileUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/books/cb01526328e3225325323939d19f2f7ce7ea78c7adbc70c1f0cb2de9e324e125.epub","fileSizeBytes":52908,"contentHash":"cb01526328e3225325323939d19f2f7ce7ea78c7adbc70c1f0cb2de9e324e125","contentVersion":1,"source":"Wikisource tiếng Việt","sourceUrl":"https://vi.wikisource.org/wiki/Th%C6%A1_H%E1%BB%93_Xu%C3%A2n_H%C6%B0%C6%A1ng","rights":"PUBLIC_DOMAIN_VN","rightsUrl":"https://vi.wikisource.org/wiki/Wikisource:Quy_%C4%91%E1%BB%8Bnh_b%E1%BA%A3n_quy%E1%BB%81n","editionLicense":"CC-BY-SA-4.0","isFeatured":false,"isNew":true,"isPremium":false,"entitlementType":"FREE","rating":0,"description":"Thơ Hồ Xuân Hương là tập thơ của nữ sĩ Hồ Xuân Hương, nổi tiếng với những bài thơ Nôm độc đáo. Thơ bà thường mượn hình ảnh thiên nhiên, đồ vật và cảnh vật để nói về thân phận người phụ nữ, tình yêu và những bất công xã hội. Giọng thơ vừa trào phúng, vừa trữ tình, thể hiện khát vọng sống và bản lĩnh của người phụ nữ.","coverUrl":"https://nocap-ebook-api.buiminhhien001.workers.dev/assets/covers/134f772e42002c82be7129ba7cbff8eee6741191876830d918f832810e550963.jpg","license":"Phạm vi công cộng (Wikisource)"}' WHERE id = 'ws-vi-tho-ho-xuan-huong';
